/* ---------------- 校验侧守门：重复 media id 一律 ERROR（PHASE 11） ---------------- */
const validate_expedition_1 = require("../../engine/validate-expedition");
function validateRuntimeManifests() {
    const issues = [];
    for (const m of exports.RUNTIME_MANIFESTS) {
        for (const i of (0, validate_expedition_1.validateMediaManifest)(m).issues) {
            if (i.level === "error")
                issues.push(`${m.id}: ${i.path} ${i.message}`);
        }
    }
    // 跨清单重复 id 检测（首个声明者胜出是查询行为，但正式内容不允许冲突声明）
    const seen = new Map();
    for (const m of exports.RUNTIME_MANIFESTS) {
        for (const a of m.assets) {
            if (seen.has(a.id)) {
                issues.push(`duplicate-media-id: ${a.id} 同时声明于 ${seen.get(a.id)} 与 ${m.id}`);
            }
            else {
                seen.set(a.id, m.id);
            }
        }
    }
    return issues;
}
